DO $migration$
DECLARE definition text:=pg_get_functiondef('public.phase6_create_agreement(uuid,text,text,uuid)'::regprocedure);
BEGIN
 IF strpos(definition,'p_request_id uuid)')=0 OR strpos(definition,$old$'template_version',1,$old$)=0 OR strpos(definition,$old$'tenant_phone',a.phone,$old$)=0 THEN RAISE EXCEPTION 'Agreement function changed; review before updating'; END IF;
 definition:=replace(definition,'p_request_id uuid)','p_request_id uuid, p_details jsonb)');
 definition:=replace(definition,' SELECT * INTO t FROM public.tenancies',$new$
 IF p_details IS NULL OR jsonb_typeof(p_details)<>'object' THEN RAISE EXCEPTION 'Agreement details must be an object'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(p_details) e WHERE e.key NOT IN ('landlord_nric','tenant_occupation','witness_name','witness_nric','payment_method','bank_name','account_holder','bank_account','payment_day','utility_deposit','inventory') OR jsonb_typeof(e.value)<>'string' OR length(e.value #>> '{}')>CASE WHEN e.key='inventory' THEN 4000 ELSE 160 END) THEN RAISE EXCEPTION 'Invalid agreement detail'; END IF;
 IF coalesce(nullif(p_details->>'payment_day',''),'1') !~ '^([1-9]|[12][0-9]|3[01])$' OR coalesce(nullif(p_details->>'utility_deposit',''),'0') !~ '^[0-9]+([.][0-9]{1,2})?$' THEN RAISE EXCEPTION 'Enter a valid payment day and utility deposit'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each_text(p_details) e WHERE e.key IN ('landlord_nric','witness_nric') AND btrim(e.value)<>'' AND regexp_replace(e.value,'[-[:space:]]','','g') !~ '^[0-9]{12}$') THEN RAISE EXCEPTION 'NRIC must contain 12 digits'; END IF;
 SELECT * INTO t FROM public.tenancies$new$);
 definition:=replace(definition,$old$OR prior.draft_snapshot->>'additional_terms' IS DISTINCT FROM coalesce(p_additional_terms,'')$old$,$new$OR prior.draft_snapshot->>'additional_terms' IS DISTINCT FROM coalesce(p_additional_terms,'') OR prior.draft_snapshot->'agreement_details' IS DISTINCT FROM p_details$new$);
 definition:=replace(definition,' SELECT * INTO a FROM public.applications',$new$
 IF coalesce(nullif(p_details->>'utility_deposit',''),'0')::numeric>t.deposit_amount THEN RAISE EXCEPTION 'Utility deposit must be included within the agreed tenancy deposit'; END IF;
 SELECT * INTO a FROM public.applications$new$);
 definition:=replace(definition,'Tenant2Care tenancy draft v1','Perjanjian Penyewaan Rumah untuk Kediaman v2');
 definition:=replace(definition,$old$'template_version',1,$old$,$new$'template_version',2,'agreement_details',p_details,'agreement_terms',$terms${"tenant":[{"text":"Membayar sewa pada tarikh seperti mana ditetapkan di JADUAL PERTAMA."},{"text":"Bertanggungjawab membayar bil-bil air dan elektrik yang dikenakan pada rumah tersebut."},{"text":"Penyewa tidak dibenarkan memasang kunci tambahan tanpa kebenaran bertulis daripada Tuan Rumah. Tuan Rumah akan diberikan pendua kesemua kunci yang dipasang atas tanggungan penyewa, sebelum ia dipasang."},{"text":"Penyewa bersetuju untuk menyewa rumah tersebut dalam keadaan baik serta bersih dan menyerahkan kembali dalam keadaan sama atau lebih baik kepada Tuan Rumah dan menanggung bayaran membersih jika Tuan Rumah mengupah orang untuk membersihkannya apabila tempoh perjanjian penyewaan ini tamat ataupun ditamatkan mengikut syarat-syarat yang terkandung dalam perjanjian."},{"text":"Membaiki sebarang kerosakan besar yang menimpa ke atas rumah tersebut yang mana ianya bukan disebabkan oleh kelalaian dan juga memperbaiki apa-apa kerosakan biasa yang disebabkan oleh “Fair Wear and Tear” dan Tuan Rumah bertanggungjawab bagi mengawas dan mengurus segala kerja-kerja pembaikan ke atas rumah tersebut di sepanjang tempoh penyewaan ini."},{"text":"Penyewa hanya dibenarkan menggunakan ruang dapur sahaja untuk memasak."},{"text":"Tidak menyewakan atau menyerahkan sama ada secara keseluruhan dan/atau sebahagian dari ruang rumah tersebut kepada orang lain tanpa terlebih dahulu mendapat kebenaran dari Tuan Rumah. Sekiranya penyewa mengingkari kehendak dan maksud perenggan ini, Tuan Rumah berhak mengutip kesemua bayaran sewa yang dibayar oleh orang lain dan/atau seterusnya mengambil apa-apa tindakan seperti mana yang ditetapkan dalam surat perjanjian ini."},{"text":"Tidak akan menyimpan dan/atau membiak sebarang haiwan di dalam kawasan rumah dan/atau di mana sahaja dalam rumah tersebut."},{"text":"Tidak membawa dan/atau menyimpan di dalam rumah apa jua jenis senjata, bahan letupan, bahan beracun dan/atau bahan berbahaya yang mudah meletup dan/atau yang mudah terbakar kecuali setelah memenuhi tuntutan undang-undang dan mendapat kebenaran dari pihak berkuasa berkenaan dan persetujuan Tuan Rumah."},{"text":"Tidak membenarkan atau memberi kebenaran bagi apa jua perkara yang melanggar undang-undang, undang-undang kecil atau peraturan kerajaan atau mana-mana pihak berkuasa yang lain yang melibatkan rumah berkenaan atau yang boleh menyebabkan polisi insurans yang melindunginya daripada kerugian atau kemusnahan akibat kebakaran menjadi tidak sah atau menyebabkan premiumnya bertambah."},{"text":"Tidak melakukan dan/atau membenarkan sesiapa sahaja melakukan apa jua perbuatan sumbang atau salah laku atau sebarang perbuatan yang menyalahi undang-undang di rumah tersebut yang boleh mengganggu suasana atau ketenteraman atau menimbulkan rasa tidak senang penduduk di kawasan tersebut."},{"text":"Membenarkan Tuan Rumah atau wakil yang telah diberikan kuasa olehnya atau pekerja-pekerja yang diupah pada bila-bila masa sahaja yang munasabah memasuki rumah tersebut untuk membuat pemeriksaan atau pembaikan yang Tuan Rumah menganggap mustahak."},{"text":"Bertanggungjawab membaiki sebarang kerosakan yang berjumlah RM200.00 dan ke bawah yang disebabkan oleh penyewa, pekerja-pekerja yang diupah penyewa atau pelawat dengan kebenaran penyewa kepada kawasan bangunan, longkang ataupun lain-lain bahagian yang berkenaan, atau membayar balik kepada Tuan Rumah semua perbelanjaan bagi membaiki kerosakan yang disebabkan oleh penyewa. Kerosakan-kerosakan biasa yang berjumlah RM200.00 dan ke bawah adalah seperti:","items":["Kerosakan pam mangkuk tandas.","Kerosakan starter lampu.","Kerosakan mentol lampu.","Kerosakan kipas.","Kerosakan tombol pintu.","Kerosakan pili air.","Kerosakan katil.","Kerosakan almari.","Kerosakan perabot."]}],"landlord":[{"text":"Akan membayar Cukai Pintu, Cukai Tanah dan bayaran selenggaraan yang dikenakan ke atas rumah tersebut."},{"text":"Memastikan langkah-langkah keselamatan rumah telah dibuat sebelum penyewa mendiami rumah seperti pemasangan jeriji besi, tombol pintu dan tingkap berada dalam keadaan baik, serta sistem pendawaian rumah dan bekalan air boleh digunakan dengan baik dan selamat."},{"text":"Bertanggungjawab membayar bil penyelenggaraan setiap bulan tanpa gagal."},{"text":"Membaiki sebarang kerosakan besar yang menimpa ke atas rumah tersebut yang bukan disebabkan oleh kelalaian penyewa dan juga memperbaiki apa-apa kerosakan biasa yang disebabkan oleh “Fair Wear and Tear”. Tuan Rumah bertanggungjawab bagi mengawas dan mengurus segala kerja-kerja pembaikan ke atas rumah tersebut di sepanjang tempoh penyewaan ini."},{"text":"Tuan Rumah akan mengembalikan wang cagaran kepada penyewa pada hari penghujung penyewaan ini tertakluk kepada syarat-syarat di mana wang cagaran boleh digunakan bagi menjelaskan sewa rumah yang tertunggak dan/atau perbelanjaan memperbaiki kerosakan atau kemusnahan daripada perbuatan sengaja, cuai atau lalai pihak penyewa, kakitangan dan/atau wakilnya; untuk bayaran yang dikenakan ke atas penyewa mengikut perjanjian ini; dan/atau perbelanjaan Tuan Rumah bagi mengekalkan keadaan rumah seperti keadaan semasa perjanjian ini ditandatangani."}],"mutual":[{"text":"Tuan Rumah berhak untuk menamatkan tempoh penyewaan ini sekiranya berlaku pelanggaran atau apabila Tuan Rumah berkehendakkan semula rumah tersebut bagi apa-apa tujuan dengan mengemukakan tidak kurang dari satu (1) bulan notis bertulis kepada penyewa."},{"text":"Penyewa berhak menamatkan penyewaan dengan memberi notis bertulis tidak kurang dari satu (1) bulan kepada Tuan Rumah atau wang cagaran tidak akan dikembalikan."},{"text":"Penamatan oleh penyewa tidak akan melepaskan penyewa dari membayar kepada Tuan Rumah apa-apa bayaran yang tertunggak seperti yang dinyatakan dalam perjanjian ini."},{"text":"Sebarang pertikaian di antara Tuan Rumah dan penyewa mengenai penyewaan rumah tersebut hendaklah diselesaikan secara aman dan baik. Jika penyelesaian tidak dapat dicapai, hendaklah diselesaikan melalui timbang tara."},{"text":"Sekiranya penyewa ingin menamatkan perjanjian sewa ini sebelum tempohnya berakhir, penyewa akan kehilangan deposit sekiranya tidak memberi notis bertulis tidak kurang dari satu (1) bulan kepada Tuan Rumah dan deposit sekuriti tidak akan dipulangkan walau apa pun yang terjadi termasuklah:","items":["Dipindahkan tempat berkhidmat atau tempat bekerja.","Ditamatkan perkhidmatan/pengajian atau dibuang kerja/kolej/universiti.","Berlaku kematian ahli keluarga.","Kesakitan ahli keluarga dan perlu pulang ke pangkuan keluarga."]},{"text":"Tuan Rumah berhak untuk menamatkan tempoh penyewaan ini sekiranya berlaku pelanggaran atau apabila Tuan Rumah berkehendakkan semula rumah tersebut bagi apa-apa tujuan dengan mengemukakan tidak kurang dari satu (1) bulan notis bertulis kepada penyewa."},{"text":"Sebarang kecurian ke atas barang-barang milik peribadi penyewa adalah atas tanggungan penyewa sendiri. Tuan Rumah tidak akan bertanggungjawab ke atas kehilangan/kecurian yang berlaku."},{"text":"Tuan Rumah berhak untuk tidak memperbaharui tempoh penyewaan."},{"text":"Segala kelengkapan/perkakasan elektrik dan perabot yang disediakan oleh Tuan Rumah hendaklah dijaga dan digunakan sebaiknya. Jika terdapat kerosakan disebabkan oleh penyewa, adalah menjadi tanggungjawab penyewa untuk menggantikan semula dan memaklumkan Tuan Rumah. Jika berlaku kerosakan disebabkan oleh pihak Tuan Rumah, adalah menjadi tanggungjawab Tuan Rumah."}]}$terms$::jsonb,$new$);
 definition:=replace(definition,$old$'tenant_phone',a.phone,$old$,$new$'tenant_phone',a.phone,'tenant_identity_card_number',a.identity_card_number,'tenant_address',a.address,'tenant_working_address',a.working_address,$new$);
 EXECUTE definition;
END;
$migration$;
REVOKE ALL ON FUNCTION public.phase6_create_agreement(uuid,text,text,uuid,jsonb) FROM PUBLIC,anon;
